#include <vector>
#include <iostream>

int main() {
    std::vector<int> c = {1, 2, 3, 4};  // Initialize a vector
    auto it = c.begin() + 2;  // Iterator points to the third element (3)
    it = c.insert(it, 5);     // Insert 5 before the element at 'it'
                             // Now c is {1, 2, 5, 3, 4} and 'it' points to 5
    for (const auto& elem : c) {
        std::cout << elem << ' ';  // Output: 1 2 5 3 4
    }
    std::cout << std::endl;
    return 0;
}
